#!/usr/bin/env python3
"""Build a manifest of all icon DIDs reachable from our shipped catalogs.

The manifest powers the opt-in bulk-preload mode (Wave 15 / Phase 15.3,
opt-in via `?preloadIcons=1` URL flag). It's a flat list of unique icon
DIDs so the boot-time fetcher can pull them via `fetch_surface_pixels`
without re-scanning every weenie at runtime.

Sources scanned
---------------
1. `apps/holtburger-web/data/spells-catalog.json`
   Each spell carries an `icon: 0x06xxxxxx` DID — already extracted by
   `scripts/build_spells_catalog.py` (LSD `iconID` → `spell.icon`).

2. `external/LSD-Partial-2025-02-23_16-15/weenies/*.json`
   Per-weenie property dump. The icon-typed DIDs live in `didStats`
   under these keys (per
   `crates/holtburger-common/src/properties/property_keys/data_ids.rs`):
     - key 8  = PropertyDataId.Icon         (the primary item icon)
     - key 50 = PropertyDataId.IconOverlay
     - key 51 = PropertyDataId.IconOverlaySecondary
     - key 52 = PropertyDataId.IconUnderlay

3. `apps/holtburger-web/data/dye-recipes.json` — no icon refs (verified;
   recipe outputs only carry paletteTemplate + shade), but the file is
   listed in `_sources` for transparency.

Output
------
`apps/holtburger-web/data/icon-manifest.json` — flat list under
`iconIds` plus a `_stats` block for cite-able counts.

To regenerate:
  python3 external/holtburger/apps/holtburger-web/scripts/build_icon_manifest.py
"""

import json
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]  # apps/holtburger-web
SPELLS_CATALOG = ROOT / "data" / "spells-catalog.json"
DYE_RECIPES = ROOT / "data" / "dye-recipes.json"
WEENIE_DIR_DEFAULT = (
    ROOT.parents[2] / "LSD-Partial-2025-02-23_16-15" / "weenies"
)
WEENIE_DIR = Path(os.environ.get("LSD_WEENIE_DIR", str(WEENIE_DIR_DEFAULT)))
OUT = ROOT / "data" / "icon-manifest.json"

# Per crates/holtburger-common/src/properties/property_keys/data_ids.rs:
#   Icon = 8, IconOverlay = 50, IconOverlaySecondary = 51, IconUnderlay = 52
ICON_DID_KEYS = {8, 50, 51, 52}


def from_spells_catalog(out: set) -> int:
    """Pull spell `icon` DIDs from the spells-catalog. Returns count."""
    before = len(out)
    if not SPELLS_CATALOG.exists():
        print(f"  WARN: spells-catalog missing: {SPELLS_CATALOG}", file=sys.stderr)
        return 0
    src = json.loads(SPELLS_CATALOG.read_text())
    for sid, spell in (src.get("spells") or {}).items():
        icon = spell.get("icon", 0)
        if isinstance(icon, int) and icon > 0:
            out.add(icon)
    return len(out) - before


def from_lsd_weenies(out: set) -> int:
    """Pull icon-typed DIDs from every LSD weenie's `didStats`. Returns
    count of newly-discovered IDs (excluding duplicates already in
    `out`)."""
    before = len(out)
    if not WEENIE_DIR.exists():
        print(f"  WARN: LSD weenie dir missing: {WEENIE_DIR}", file=sys.stderr)
        return 0
    scanned = 0
    skipped = 0
    for f in WEENIE_DIR.iterdir():
        if not f.name.endswith(".json"):
            continue
        scanned += 1
        try:
            doc = json.loads(f.read_text())
        except Exception as e:
            skipped += 1
            if skipped <= 5:
                print(f"  WARN: failed to parse {f.name}: {e}", file=sys.stderr)
            continue
        for entry in doc.get("didStats") or []:
            key = entry.get("key")
            val = entry.get("value", 0)
            if key in ICON_DID_KEYS and isinstance(val, int) and val > 0:
                out.add(val)
    print(f"  scanned {scanned} weenies ({skipped} skipped)")
    return len(out) - before


def from_dye_recipes(out: set) -> int:
    """Dye recipes don't carry icon DIDs (paletteTemplate + shade only).
    Listed in sources for transparency; returns 0."""
    before = len(out)
    if not DYE_RECIPES.exists():
        return 0
    src = json.loads(DYE_RECIPES.read_text())
    # Defensive — scan in case future versions add icons.
    for _wcid, rec in (src.get("dyePots") or {}).items():
        icon = rec.get("icon") or rec.get("iconId") or 0
        if isinstance(icon, int) and icon > 0:
            out.add(icon)
    return len(out) - before


def main() -> int:
    icons: set[int] = set()

    print(f"reading spells-catalog: {SPELLS_CATALOG}")
    from_spells = from_spells_catalog(icons)
    print(f"  +{from_spells} unique icon DIDs from spells")

    print(f"reading LSD weenies: {WEENIE_DIR}")
    from_weenies = from_lsd_weenies(icons)
    print(f"  +{from_weenies} unique icon DIDs from weenies")

    print(f"reading dye recipes: {DYE_RECIPES}")
    from_dyes = from_dye_recipes(icons)
    print(f"  +{from_dyes} unique icon DIDs from dye recipes")

    ids_sorted = sorted(icons)
    out_doc = {
        "_comment": (
            "Generated by scripts/build_icon_manifest.py. Powers the "
            "opt-in bulk-preload at boot (Wave 15 / `?preloadIcons=1`). "
            "Sources: spells-catalog.json (spell.icon), LSD-Partial "
            "weenies/*.json didStats keys 8/50/51/52 "
            "(PropertyDataId.Icon/IconOverlay/IconOverlaySecondary/"
            "IconUnderlay per crates/holtburger-common/src/properties/"
            "property_keys/data_ids.rs), dye-recipes.json (no icons, "
            "scanned defensively). To regenerate: "
            "python3 external/holtburger/apps/holtburger-web/scripts/"
            "build_icon_manifest.py"
        ),
        "_sources": [
            "data/spells-catalog.json",
            "external/LSD-Partial-2025-02-23_16-15/weenies/",
            "data/dye-recipes.json",
        ],
        "_stats": {
            "totalUnique": len(ids_sorted),
            "fromSpells": from_spells,
            "fromWeenies": from_weenies,
            "fromDyes": from_dyes,
        },
        "iconIds": ids_sorted,
    }

    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps(out_doc, separators=(",", ":")))
    print(
        f"wrote {len(ids_sorted)} icon DIDs -> {OUT} "
        f"({OUT.stat().st_size / 1024:.1f} KB)"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
